import sys

def main():
    data = sys.stdin.read().split()
    n, W = int(data[0]), int(data[1])
    items = [(int(data[2 + 3 * i]), int(data[3 + 3 * i]), int(data[4 + 3 * i])) for i in range(n)]
    # dp0[c]: best profit with total weight <= c and no change used
    # dp1[c]: best profit with total weight <= c and at most one change used
    dp0 = [0] * (W + 1)
    dp1 = [0] * (W + 1)
    for w, a, p in items:
        for c in range(W, 0, -1):
            best = dp1[c]
            if c >= w:
                v = dp1[c - w] + p
                if v > best:
                    best = v
            if c >= a:
                v = dp0[c - a] + p
                if v > best:
                    best = v
            dp1[c] = best
            if c >= w:
                v = dp0[c - w] + p
                if v > dp0[c]:
                    dp0[c] = v
    print(dp1[W])

main()

