a = [int(data[3 + 3 * i]) for i in range(n)]
p = [int(data[4 + 3 * i]) for i in range(n)]
best = 0
for changed in range(-1, n):
    ws = list(w)
    if changed >= 0:
        ws[changed] = a[changed]
    for mask in range(1 << n):
        tw = tp = 0
        for i in range(n):
            if mask >> i & 1:
                tw += ws[i]
                tp += p[i]
        if tw <= W and tp > best:
            best = tp
